#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

void merge_runs(const vector<long long>& source, vector<long long>& destination,
                int left, int middle, int right) {
    int first = left;
    int second = middle;
    int output = left;

    while (first < middle && second < right) {
        if (source[first] <= source[second]) {
            destination[output] = source[first];
            first++;
        } else {
            destination[output] = source[second];
            second++;
        }
        output++;
    }
    while (first < middle) {
        destination[output] = source[first];
        first++;
        output++;
    }
    while (second < right) {
        destination[output] = source[second];
        second++;
        output++;
    }
}

void sort_values(vector<long long>& values) {
    int n = static_cast<int>(values.size());
    vector<long long> buffer(n);

    for (int width = 1; width < n; width *= 2) {
        for (int left = 0; left < n; left += 2 * width) {
            int middle = min(left + width, n);
            int right = min(left + 2 * width, n);
            merge_runs(values, buffer, left, middle, right);
        }
        values.swap(buffer);
    }
}

int count_distinct(const vector<long long>& values) {
    int count = 0;
    for (int i = 0; i < static_cast<int>(values.size()); i++) {
        if (i == 0 || values[i] != values[i - 1]) {
            count++;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> values(n);
    for (long long& value : values) {
        cin >> value;
    }
    sort_values(values);
    cout << count_distinct(values) << '\n';
    return 0;
}

